"OLAYLAR_ORTACAG_ORTADOGU:0744-12-07:0":{"b": ["Մարվան II-ը հռչակվեց խալիֆա", "f51a800a"], "d": ["Այնտեղ գտնվողները Մարվանին հռչակեցին խալիֆա (26 Սաֆար 127 / 744 թ. դեկտեմբերի 7). սկսվեց վերջին Օմայյան խալիֆայի շրջանը։", "1bc682b5"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-01-01:0":{"b": ["Մարվան II-ը Սիրիան հպատակեցրեց. քանդել տվեց Հոմսի, Բաալբեքի, Դամասկոսի և Երուսաղեմի պարիսպները", "468a2d97"], "d": ["Հնարավոր ապստամբությունները կանխելու համար Սիրիայի քաղաքների պարիսպները քանդել տված Մարվանը 128 (746) թվականի ամռանը Սիրիան հպատակեցրեց։", "afc53641"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-09-22:0":{"b": ["Խարիջյան (իբադի) առաջնորդ Թալիբ ալ-Հաքը Հադրամաուտից հետո Սանան վերցրեց Օմայյաններից (129/746)", "d56ff983"], "d": ["Աբդուլլահ բ. Յահյա ալ-Հադրամին (Թալիբ ալ-Հաք) Օմանի իբադիների աջակցությամբ ապստամբեց Օմայյանների դեմ, իրեն հռչակեց խալիֆա. Հադրամաուտից հետո գրավեց Սանան։ Այնուհետև շարժվելով Մեքքայի և Մեդինայի վրա՝ պարտվեց Մարվան II-ի ուժերին և սպանվեց Սանայի մոտ (130/748)։", "a2697365"]},
"OLAYLAR_ORTACAG_ORTADOGU:0747-01-01:0":{"b": ["Աբու Մուսլիմի առաջնորդությամբ Խորասանում բացահայտ սկսվեց Աբբասյան հեղաշրջումը (129/747)։", "92a5194c"], "d": ["Աբու Մուսլիմի առաջնորդությամբ Խորասանում բացահայտ սկսվեց Աբբասյան հեղաշրջումը (129/747)։", "92a5194c"]},
"OLAYLAR_ORTACAG_ORTADOGU:0749-11-28:0":{"b": ["Կուֆայում Աբու ալ-Աբբասին տրվեց հավատարմության երդում. հիմնվեց Աբբասյան խալիֆայությունը", "a0c563ae"], "d": ["Կուֆայում Աբու ալ-Աբբասին տրվեց հավատարմության երդում. հիմնվեց Աբբասյան խալիֆայությունը", "a0c563ae"]},
"OLAYLAR_ORTACAG_ORTADOGU:0750-01-16:0":{"b": ["Սկսվեց Զաբի ճակատամարտը. Աբդուլլահ բ. Ալին, հաղթելով Մարվան II-ին, ցրեց Օմայյան բանակը։", "d9b81d02"], "d": ["Սկսվեց Զաբի ճակատամարտը. Աբդուլլահ բ. Ալին, հաղթելով Մարվան II-ին, ցրեց Օմայյան բանակը։", "d9b81d02"]},
"OLAYLAR_ORTACAG_ORTADOGU:0750-01-25:0":{"b": ["Մեծ Զաբ. Մարվան II-ը ծանր ջախջախիչ պարտություն կրեց Աբբասյաններից", "8d223056"], "d": ["2 Ջումադա աս-սանիյա 132-ին (750 թ. հունվարի 16) սկսված ճակատամարտը ավարտվեց 11 Ջումադա աս-սանիյա շաբաթ օրը (հունվարի 25) առավոտյան Մարվանի ծանր պարտությամբ։", "cb560e7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0754-01-01:0":{"b": ["Մանսուրը դարձավ խալիֆա (754-775). սկսվեց շրջանը, երբ նա համարվում է խալիֆայության իրական հիմնադիրը։", "cf491add"], "d": ["Մանսուրը դարձավ խալիֆա (754-775). սկսվեց շրջանը, երբ նա համարվում է խալիֆայության իրական հիմնադիրը։", "cf491add"]},
