"OLAYLAR_ORTACAG_ORTADOGU:1070-07-31:0":{"b": ["Մահմուդը, ընդունելով սելջուկյան տիրապետությունը, խուտբան կարդացնել տվեց Աբբասյան խալիֆայի և սուլթան Ալփ Արսլանի անունով (19 Շավվալ 462)։", "a2335885"], "d": ["Մահմուդը, ընդունելով սելջուկյան տիրապետությունը, խուտբան կարդացնել տվեց Աբբասյան խալիֆայի և սուլթան Ալփ Արսլանի անունով (19 Շավվալ 462)։", "a2335885"]},
"OLAYLAR_ORTACAG_ORTADOGU:1072-01-01:0":{"b": ["Երբ Հասան բ. Ամմարը անզավակ մահացավ, նրա եղբորորդիներ Ջալալ ալ-Մուլկ Ալիի և Ֆախր ալ-Մուլկի միջև սկսվեց իշխանության պայքար. կառավարման անցավ Ջալալ ալ-Մուլկը։", "889f4c7d"], "d": ["Երբ Հասան բ. Ամմարը անզավակ մահացավ, նրա եղբորորդիներ Ջալալ ալ-Մուլկ Ալիի և Ֆախր ալ-Մուլկի միջև սկսվեց իշխանության պայքար. կառավարման անցավ Ջալալ ալ-Մուլկը։", "889f4c7d"]},
"OLAYLAR_ORTACAG_ORTADOGU:1073-01-01:0":{"b": ["Սովի և ներքին խառնաշփոթի ժամանակ Աքքայի կուսակալ Բադր ալ-Ջամալին հրավիրվեց Կահիրե, Իլդեգիզի ձերբակալությամբ ստանձնեց վեզիրությունը և կառավարումը (1073 թ. հունվար)։", "c7415494"], "d": ["Սովի և ներքին խառնաշփոթի ժամանակ Աքքայի կուսակալ Բադր ալ-Ջամալին հրավիրվեց Կահիրե, Իլդեգիզի ձերբակալությամբ ստանձնեց վեզիրությունը և կառավարումը (1073 թ. հունվար)։", "c7415494"]},
"OLAYLAR_ORTACAG_ORTADOGU:1075-01-01:0":{"b": ["Մահմուդը մահացավ. նրան հաջորդեց Ջալալ ալ-Դաուլա Նասր բ. Մահմուդը։", "6c84021b"], "d": ["Մահմուդը մահացավ. նրան հաջորդեց Ջալալ ալ-Դաուլա Նասր բ. Մահմուդը։", "6c84021b"]},
"OLAYLAR_ORTACAG_ORTADOGU:1076-08-05:0":{"b": ["Լահսան յոթնամյա պաշարման ավարտին անցավ Ույունիների ձեռքը. Ղարմաթները դուրս եկան Լահսայից (469/1076)", "848f5122"], "d": ["Աբդ ալ-Կայս ցեղի Բանի Մուռա ճյուղից Աբդուլլահ բ. Ալի ալ-Ույունին յոթ տարի տևած պաշարման ավարտին գրավեց Լահսան (469/1076). այս իրադարձությամբ Բահրեյնի Ղարմաթյան պետության տիրապետությունը Լահսայում ավարտվեց։ Ատլասում Լահսան այս թվականից հետո հայտարարված դատարկություն է (Ույունիները քարտ չունեն)։", "24e62364"]},
"OLAYLAR_ORTACAG_ORTADOGU:1080-06-18:0":{"b": ["Ուկայլյան Մուսլիմ բ. Կուրայշը մտավ Հալեպ. Միրդասյան տիրապետությունն ավարտվեց (միջնաբերդը՝ 1080 թ. հոկտեմբեր)", "fb6ea907"], "d": ["Ուկայլյան Մուսլիմ բ. Կուրայշը մտավ Հալեպ. Միրդասյան տիրապետությունն ավարտվեց (միջնաբերդը՝ 1080 թ. հոկտեմբեր)", "fb6ea907"]},
"OLAYLAR_ORTACAG_ORTADOGU:1080-10-01:0":{"b": ["Մուսլիմ բ. Կուրայշը վերցրեց Հալեպի միջնաբերդը և վերջ դրեց Միրդասյանների տիրապետությանը (Ռաբի աս-սանի 473)", "8a9f670c"], "d": ["Ուկայլյան Մուսլիմ բ. Կուրայշը 26 Զու-լ-հիջջա 472-ին (1080 թ. հունիսի 18) մտավ Հալեպ քաղաք. Ռաբի աս-սանի 473-ին (1080 թ. հոկտեմբեր), վերցնելով միջնաբերդը, վերջ դրեց Միրդասյանների տիրապետությանը Հալեպում։", "26ab1048"]},
"OLAYLAR_ORTACAG_ORTADOGU:1092-01-01:0":{"b": ["Մելիքշահի մահն իմանալով՝ Թութուշը հռչակեց իր սուլթանությունը (1092 թ. նոյեմբեր)։", "53f7b9f0"], "d": ["Մելիքշահի մահն իմանալով՝ Թութուշը հռչակեց իր սուլթանությունը (1092 թ. նոյեմբեր)։", "53f7b9f0"]},
