"OLAYLAR_ORTACAG_ORTADOGU:1094-12-29:0":{"b": ["Մուստանսիր Բիլլահը մահացավ. վեզիր Աֆդալը Մուստալիին հռչակեց խալիֆա, և այս իրադարձությունը հանգեցրեց Ֆաթիմյան իսմայիլիության երկատմանը՝ Մուստալիյա և Նիզարիյա (18 Զու-լ-հիջջա 487)։", "ca5d4aff"], "d": ["Մուստանսիր Բիլլահը մահացավ. վեզիր Աֆդալը Մուստալիին հռչակեց խալիֆա, և այս իրադարձությունը հանգեցրեց Ֆաթիմյան իսմայիլիության երկատմանը՝ Մուստալիյա և Նիզարիյա (18 Զու-լ-հիջջա 487)։", "ca5d4aff"]},
"OLAYLAR_ORTACAG_ORTADOGU:1095-02-26:0":{"b": ["Թութուշի մահով պետությունը երկատվեց. նրա որդի Ռիդվանը Հալեպում, իսկ նրա եղբայր Դուքաքը Դամասկոսում հիմնեցին առանձին մելիքություններ։", "10171277"], "d": ["Թութուշի մահով պետությունը երկատվեց. նրա որդի Ռիդվանը Հալեպում, իսկ նրա եղբայր Դուքաքը Դամասկոսում հիմնեցին առանձին մելիքություններ։", "10171277"]},
"OLAYLAR_ORTACAG_ORTADOGU:1097-08-28:0":{"b": ["Ռիդվանը Հալեպում խուտբան կարդացնել տվեց Ֆաթիմյան խալիֆայի անունով. սուննի հակազդեցության պատճառով մոտ չորս շաբաթ անց հրաժարվեց և ներողություն խնդրեց Աբբասյան խալիֆայից (17 Ռամադան 490)։", "5103d531"], "d": ["Ռիդվանը Հալեպում խուտբան կարդացնել տվեց Ֆաթիմյան խալիֆայի անունով. սուննի հակազդեցության պատճառով մոտ չորս շաբաթ անց հրաժարվեց և ներողություն խնդրեց Աբբասյան խալիֆայից (17 Ռամադան 490)։", "5103d531"]},
"OLAYLAR_ORTACAG_ORTADOGU:1098-03-10:0":{"b": ["Բոդուեն դը Բուլոնը Ուրֆայում հռչակեց իր տիրապետությունը. հիմնվեց առաջին խաչակրաց պետությունը", "d8e0e2c5"], "d": ["Բոդուեն դը Բուլոնը Ուրֆայում հռչակեց իր տիրապետությունը. հիմնվեց առաջին խաչակրաց պետությունը", "d8e0e2c5"]},
"OLAYLAR_ORTACAG_ORTADOGU:1098-05-04:0":{"b": ["Քյուրբողայի սելջուկյան բանակը երեք շաբաթ պաշարեց Ուրֆան (1098 թ. մայիսի 4-25) և նահանջեց՝ չկարողանալով վերցնել։", "b121473d"], "d": ["Քյուրբողայի սելջուկյան բանակը երեք շաբաթ պաշարեց Ուրֆան (1098 թ. մայիսի 4-25) և նահանջեց՝ չկարողանալով վերցնել։", "b121473d"]},
"OLAYLAR_ORTACAG_ORTADOGU:1098-06-03:0":{"b": ["Խաչակիրները վերցրին Անտիոքը. Բոհեմունդը հիմնեց Անտիոքի իշխանությունը", "6dfc63d0"], "d": ["Խաչակիրները վերցրին Անտիոքը (Յաղըսըյանի հրամանատար Ֆիրուզի դավաճանությամբ). Բոհեմունդը հիմնեց Անտիոքի իշխանությունը, Իսկենդերունը նույնպես մնաց իշխանության սահմաններում", "e3e731ad"]},
"OLAYLAR_ORTACAG_ORTADOGU:1099-05-16:0":{"b": ["Ռեմոն դը Սեն-Ժիլը, Ֆախր ալ-Մուլկից ստանալով 15.000 դինար և նվերներ, վերացրեց Արկայի պաշարումը։", "4609dedc"], "d": ["Ռեմոն դը Սեն-Ժիլը, Ֆախր ալ-Մուլկից ստանալով 15.000 դինար և նվերներ, վերացրեց Արկայի պաշարումը։", "4609dedc"]},
"OLAYLAR_ORTACAG_ORTADOGU:1099-06-07:0":{"b": ["Խաչակրաց բանակը հասավ Երուսաղեմի առջև և սկսեց պաշարումը", "0b356516"], "d": ["Երեքամյա երթից հետո խաչակիրները 1099 թ. հունիսի 7-ի երեքշաբթի առավոտյան հասան այն ժամանակ Ֆաթիմյանների ձեռքին գտնվող Երուսաղեմի դիմացի ամենաբարձր կետը և պաշարեցին քաղաքը. հնգաշաբաթյա պաշարումը հուլիսի 15-ին ավարտվեց քաղաքի անկումով։", "9878b195"]},
